`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------------
// TW-HBM-PGLG 2026-10-19: ot_hbm_su_static_pgslice_rg = the full LIGHT SU port-group slice in REGION (landed) form
// (landed-regions-standard-1018, lanes/LANDING-CONTRACT.md):
//   u_core   = ot_hbm_su_static_pgslice_rgf_lp: the landed serial parent generated by tools/landed_parent/lp.py from the
//              wires-only flat parent ot_hbm_su_static_pgslice_rgf (tools/hbm_static/su_pgslice_rgf_gen.py; glue
//              ot_hbm_su_pgrg_parts.sv) = the kit top of hbm_su_pgslice_lg_light_d4g (5 regions s, r0..r3 stacked
//              R0 | R1 | S | R2 | R3; 16 landings D 2 / E 1; record results/rtl/tw_hbm_pglg_1019/lp/).
//   u_stream = ot_hbm_su_static_pg_stream: the pg_clk (4:3) service (VM bank leaves, multirate bridges, LG taps, inject
//              slots) as a sibling leaf tile at the S band E face (landed clusters are single-frequency).
// Port list = ot_hbm_su_static_pgslice_lg's minus the per-child clock / reset entries (clk_lane, clk_insert, clk_bcast,
// clk_bank, clk_bank_macro, clk_side, rst_lane_n, rst_bcast_n: children are sinks of their region root and take the
// region reset runs) plus the region roots ck_s (= clk_ctl), ck_r0..3 and the pre-tree operands (HH-6 su_pt sibling).
// Offsets vs pgslice_lg (bench tb_hbm_su_pgslice_rg; compiler; HBM-PGLG2 face relays +1 incl.): frames r1/r2 +3, r0/r3 +6; red_sel, tree_cmd,
// rf_dsec issued +10; slice_x, tree_o, pt_ro_*, inj_q +11; fault +12; VM write (su_wq) +12 serial = +16 stream.
// MUT: < 100 = glue mutants (GMUT: 1/2/4/10/11 as pgslice, 20 outer relay 2 stages, 21 drain line short);
//      101..104 = lp.py landing mutants 1..4 (1 landing 0 bypassed, 2 read K+1, 3 pad 0 short, 4 u_sout reset late).
// ---------------------------------------------------------------------------------------------------------------------
module ot_hbm_su_static_pgslice_rg #(
 parameter integer QID=1,G=2,READ_RETURN=10,WRITE_RETURN=7,FETCH_EXTRA_EDGES=2,MLAT=4,ALAT=3,LEAF=1,MUT=0,MULTIRATE=1,
 parameter integer PIN_REG=1,COLLPORT=1,B39_NOOP=(QID==0),RF_LOCAL=1,RSYNC=1,RSYNC_MUT=0,STRAP=1,PRETREE=0
)(
 input wire clk_ctl, ck_r0, ck_r1, ck_r2, ck_r3, pg_clk,
 input wire rst_n,
 input wire [3:0] pos,
 input wire bridge_rst_n,
 input wire [1741:0] control,
 input wire [2*30-1:0] vmr_cmd,
 input wire [2*39-1:0] vmw_cmd,
 input wire [4*32-1:0] rf_bword,
 input wire [4*9-1:0] rf_bcmd,
 input wire [255:0] rf_dsec,
 input wire [11:0] red_sel,
 output wire [31:0] slice_x,
 input wire [11:0] tree_cmd,
 output wire [66:0] tree_o,
 output wire [1023:0] pt_ro_x,
 output wire [31:0] pt_ro_v,
 input wire [1:0] inj_rd,
 input wire [159:0] inj_addr,
 output wire [1023:0] inj_q,
 input wire [1:0] dw_v,
 input wire [17:0] dw_row,
 input wire [1023:0] dw_d,
 output wire fault,
 output wire [33:0] lg_rq,
 output wire [561:0] lg_wq,
 input wire [513:0] lg_rr,
 input wire [1:0] lg_w_done,
 input wire [1:0] lg_read,lg_write,
 input wire [33:0] far_rq,
 input wire [561:0] far_wq,
 output wire [513:0] far_rr,
 output wire [1:0] far_w_done,
 output wire lg_fault
);
 wire [561:0] su_wq; wire [513:0] su_rr; wire [3:0] ij_v; wire [35:0] ij_row; wire ij_bad, pg_fault;
 ot_hbm_su_static_pgslice_rgf_lp #(.QID(QID),.G(G),.STRAP(STRAP),.PRETREE(PRETREE),.GMUT((MUT<100)?MUT:0),
  .MUT((MUT>100)?MUT-100:0)) u_core(
  .ck_s(clk_ctl),.ck_r0(ck_r0),.ck_r1(ck_r1),.ck_r2(ck_r2),.ck_r3(ck_r3),.rst_n(rst_n),.pos(pos),.pos_r0(pos),.pos_r1(pos),.pos_r2(pos),.pos_r3(pos),.control(control),
  .vmr_cmd(vmr_cmd),.vmw_cmd(vmw_cmd),.rf_bword(rf_bword),.rf_bcmd(rf_bcmd),.rf_dsec(rf_dsec),.red_sel(red_sel),
  .slice_x(slice_x),.tree_cmd(tree_cmd),.tree_o(tree_o),.pt_ro_x(pt_ro_x),.pt_ro_v(pt_ro_v),.inj_q(inj_q),.dw_v(dw_v),
  .dw_row(dw_row),.dw_d(dw_d),.fault(fault),.su_wq(su_wq),.su_rr(su_rr),.ij_v(ij_v),.ij_row(ij_row),.ij_bad(ij_bad),
  .pg_fault(pg_fault));
 ot_hbm_su_static_pg_stream #(.QID(QID),.G(G),.READ_RETURN(READ_RETURN),.WRITE_RETURN(WRITE_RETURN),.MUT((MUT<100)?MUT:0),
  .MULTIRATE(MULTIRATE),.COLLPORT(COLLPORT),.B39_NOOP(B39_NOOP),.RSYNC(RSYNC),.RSYNC_MUT(RSYNC_MUT),.STRAP(STRAP)) u_stream(
  .clk_ctl(clk_ctl),.pg_clk(pg_clk),.rst_n(rst_n),.bridge_rst_n(bridge_rst_n),.pos(pos),.vmr_cmd(vmr_cmd),.su_wq(su_wq),
  .su_rr(su_rr),.ij_v(ij_v),.ij_row(ij_row),.ij_bad(ij_bad),.pg_fault(pg_fault),.inj_rd(inj_rd),.inj_addr(inj_addr),
  .lg_rq(lg_rq),.lg_wq(lg_wq),.lg_rr(lg_rr),.lg_w_done(lg_w_done),.lg_read(lg_read),.lg_write(lg_write),.far_rq(far_rq),
  .far_wq(far_wq),.far_rr(far_rr),.far_w_done(far_w_done),.lg_fault(lg_fault));
endmodule
`default_nettype wire
